-- 009_attempt_snapshot: atomic per-learner assignments and immutable attempt questions.
-- Existing terminal records remain truthful legacy_unavailable rows.

-- @step create_exam_assignment
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_assignment' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_assignment') = 11 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_assignment' AND ((COLUMN_NAME = 'id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('paper_id', 'user_id') AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME IN ('release_id', 'category_id') AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'source' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'difficulty' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'rule_snapshot' AND DATA_TYPE = 'json' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'snapshot_origin' AND COLUMN_TYPE = 'varchar(32)' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'created_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED') OR (COLUMN_NAME = 'updated_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED on update CURRENT_TIMESTAMP(3)'))) = 11 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_assignment') = 5 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_assignment' AND ((INDEX_NAME = 'PRIMARY' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'id') OR (INDEX_NAME = 'uk_exam_assignment_paper_user' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'paper_id') OR (INDEX_NAME = 'uk_exam_assignment_paper_user' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'user_id') OR (INDEX_NAME = 'idx_exam_assignment_user' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'user_id') OR (INDEX_NAME = 'idx_exam_assignment_release' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'release_id')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 5 THEN 1 ELSE 0 END AS complete;
CREATE TABLE IF NOT EXISTS `exam_assignment` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `paper_id` BIGINT UNSIGNED NOT NULL, `user_id` BIGINT UNSIGNED NOT NULL, `release_id` BIGINT UNSIGNED NULL, `source` VARCHAR(16) NULL, `category_id` BIGINT UNSIGNED NULL, `difficulty` VARCHAR(16) NOT NULL, `rule_snapshot` JSON NOT NULL, `snapshot_origin` VARCHAR(32) NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `uk_exam_assignment_paper_user` (`paper_id`, `user_id`), KEY `idx_exam_assignment_user` (`user_id`), KEY `idx_exam_assignment_release` (`release_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='学员在单场考试内冻结的来源类别难度与规则';

-- @step create_exam_record_question
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record_question' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record_question') = 10 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record_question' AND ((COLUMN_NAME = 'id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('record_id', 'question_id') AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'question_version_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('type', 'difficulty') AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME IN ('score_cents', 'position') AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME IN ('display_to_original', 'snapshot_json') AND DATA_TYPE = 'json' AND IS_NULLABLE = 'NO'))) = 10 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record_question') = 3 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record_question' AND ((INDEX_NAME = 'PRIMARY' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'id') OR (INDEX_NAME = 'uk_exam_record_question_position' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'record_id') OR (INDEX_NAME = 'uk_exam_record_question_position' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'position')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 3 THEN 1 ELSE 0 END AS complete;
CREATE TABLE IF NOT EXISTS `exam_record_question` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `record_id` BIGINT UNSIGNED NOT NULL, `question_id` BIGINT UNSIGNED NOT NULL, `question_version_id` BIGINT UNSIGNED NULL, `type` VARCHAR(16) NOT NULL, `difficulty` VARCHAR(16) NOT NULL, `score_cents` INT UNSIGNED NOT NULL, `position` INT UNSIGNED NOT NULL, `display_to_original` JSON NOT NULL, `snapshot_json` JSON NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uk_exam_record_question_position` (`record_id`, `position`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='每次作答冻结的个人题单与显示映射';

-- @step extend_exam_record_attempt_snapshot
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record') = 21 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND ((COLUMN_NAME = 'regulation_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('assignment_id', 'active_assignment_id', 'release_id', 'category_id') AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('source', 'difficulty') AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'rule_snapshot' AND DATA_TYPE = 'json' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'snapshot_origin' AND COLUMN_TYPE = 'varchar(32)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'legacy_unavailable'))) = 9 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record') = 17 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND ((INDEX_NAME = 'uk_assignment_attempt' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'assignment_id') OR (INDEX_NAME = 'uk_assignment_attempt' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'attempt_no') OR (INDEX_NAME = 'uk_active_assignment' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'active_assignment_id') OR (INDEX_NAME = 'idx_exam_record_release' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'release_id')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 4 THEN 1 ELSE 0 END AS complete;
ALTER TABLE `exam_record` MODIFY COLUMN `regulation_id` BIGINT UNSIGNED NULL COMMENT '制度冗余快照；培训考试为 NULL', ADD COLUMN `assignment_id` BIGINT UNSIGNED NULL AFTER `user_id`, ADD COLUMN `active_assignment_id` BIGINT UNSIGNED NULL COMMENT '仅进行中记录等于 assignment_id，终态置 NULL' AFTER `assignment_id`, ADD COLUMN `release_id` BIGINT UNSIGNED NULL AFTER `active_assignment_id`, ADD COLUMN `source` VARCHAR(16) NULL AFTER `release_id`, ADD COLUMN `category_id` BIGINT UNSIGNED NULL AFTER `source`, ADD COLUMN `difficulty` VARCHAR(16) NULL AFTER `category_id`, ADD COLUMN `rule_snapshot` JSON NULL AFTER `difficulty`, ADD COLUMN `snapshot_origin` VARCHAR(32) NOT NULL DEFAULT 'legacy_unavailable' AFTER `rule_snapshot`, ADD UNIQUE KEY `uk_assignment_attempt` (`assignment_id`, `attempt_no`), ADD UNIQUE KEY `uk_active_assignment` (`active_assignment_id`), ADD KEY `idx_exam_record_release` (`release_id`);
